def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    anchors = {}

    # A gap inside a horizontal bar marks a vertical color boundary.
    for r in range(h):
        for c in range(1, w - 1):
            if grid[r][c] != 0:
                continue
            left = next((grid[r][x] for x in range(c - 1, -1, -1)
                         if grid[r][x] != 0), 0)
            right = next((grid[r][x] for x in range(c + 1, w)
                          if grid[r][x] != 0), 0)
            if left and left == right:
                anchors.setdefault(c, []).append((r, left))

    for c, marks in anchors.items():
        marks.sort()
        # Extend the first bar's color to the top, then each later bar's
        # color from just below the prior bar through its own row.
        for i, (r, color) in enumerate(marks):
            start = 0 if i == 0 else marks[i - 1][0] + 1
            for rr in range(start, r + 1):
                out[rr][c] = color

        # A vertical line at the bottom supplies the color below the bars.
        bottom_colors = [grid[r][c] for r in range(h - 1, -1, -1)
                        if grid[r][c] != 0]
        if bottom_colors:
            marker_color = bottom_colors[0]
            last_anchor = marks[-1][0]
            for rr in range(last_anchor + 1, h):
                out[rr][c] = marker_color

    return out
